pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        vm.deal(actor, 10);
        vm.prank(actor);
        bool ok;
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Universal rule: after any play, the pot recorded in state can never
        // exceed the contract's real balance. The reference keeps this (a win
        // zeroes pot); the mutant leaves a stale pot > balance after a win.
        assertTrue(!ok || c.pot() <= address(c).balance);
    }
}

