pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        vm.warp(1);
        vm.deal(actor, 10);
        uint256 balBefore = actor.balance;
        vm.prank(actor);
        c.play{value: 10}();
        bool won = actor.balance > balBefore;
        // Rule: a winning play pays out the whole pot (minus fee) and resets pot to 0.
        assertTrue(!won || c.pot() == 0);
    }
}

