pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, address p1, address p2) public {
        vm.assume(p1 != address(0) && p1 != address(c));
        vm.assume(p2 != address(0) && p2 != address(c) && p2 != p1);
        ts = bound(ts, 1, type(uint64).max - 2048);

        vm.deal(p1, 10);
        vm.deal(p2, 10);

        // Drive p1 until they win (pot reset in reference; stale in mutant).
        bool won1 = false;
        uint256 t = ts;
        for (uint256 i = 0; i < 1024 && !won1; i++) {
            vm.warp(t);
            vm.prank(p1);
            c.play{value: 10}();
            won1 = (p1.balance == 9);
            t++;
        }
        vm.assume(won1);

        // Drive p2 until they win. Reference: pot was reset, payout = 9,
        // so p2 ends with 19. Mutant: pot still holds 10, payout = 19,
        // so p2 ends with 29.
        bool won2 = false;
        for (uint256 i = 0; i < 1024 && !won2; i++) {
            vm.warp(t);
            vm.prank(p2);
            c.play{value: 10}();
            won2 = (p2.balance > 10);
            t++;
        }

        assertTrue(!won2 || p2.balance == 19);
    }
}

