pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, uint256 diff, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        vm.assume(uint160(actor) > 100);

        uint256 TICKET = 10;
        vm.warp(ts);
        vm.roll(diff);

        uint256 expected = uint256(
            keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))
        ) % 2;

        vm.deal(actor, TICKET);
        vm.prank(actor);
        c.play{value: TICKET}();

        // General rule: a win (pot drained to 0) happens exactly on parity-0 outcomes.
        assertTrue(
            (c.pot() == 0) == (expected == 0),
            "win condition must match parity of keccak256(timestamp,difficulty,sender)"
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public {
        uint amt = 10;
        require(address(this).balance >= 2 * amt);
        c.play{value: amt}();
        c.play{value: amt}();
        uint p = c.pot();
        assert(p == 0 || p == 2 * amt);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runTest(uint amount) public {
        require(address(this).balance >= amount);
        c.play{value: amount}();
        assert((address(c).balance == 0 && c.pot() == 0) ||
               (address(c).balance == amount && c.pot() == amount));
    }

    receive() external payable {}
    fallback() external payable {}
}

